// Hand-added regression test for the OAuth scope fix (GH servosity/msp-skills#7).
// NOT generated by the Printing Press; guards that `auth login` mints the
// client_credentials token WITH the OAuth2 scope parameter.

package cli

import (
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"testing"
)

// mintClientCredentialsToken is the path `halopsa-cli auth login` uses. Before
// the fix it omitted scope entirely, so HaloPSA returned a token that 401'd on
// every API call. This asserts the scope is sent when provided and omitted when
// empty.
func TestMintClientCredentialsTokenSendsScope(t *testing.T) {
	cases := []struct {
		name      string
		scope     string
		wantScope string
		wantKey   bool
	}{
		{"default all", "all", "all", true},
		{"narrow override", "read:tickets", "read:tickets", true},
		{"empty omits", "", "", false},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			var gotForm url.Values
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				body, _ := io.ReadAll(r.Body)
				gotForm, _ = url.ParseQuery(string(body))
				w.Header().Set("Content-Type", "application/json")
				_, _ = w.Write([]byte(`{"access_token":"tok","expires_in":3600}`))
			}))
			defer srv.Close()

			tok, err := mintClientCredentialsToken(srv.Client(), srv.URL, "cid", "csecret", tc.scope)
			if err != nil {
				t.Fatalf("mint: %v", err)
			}
			if tok.AccessToken != "tok" {
				t.Fatalf("access_token = %q, want %q", tok.AccessToken, "tok")
			}
			if gotForm.Get("grant_type") != "client_credentials" {
				t.Fatalf("grant_type = %q, want client_credentials", gotForm.Get("grant_type"))
			}
			if gotForm.Get("client_id") != "cid" || gotForm.Get("client_secret") != "csecret" {
				t.Fatalf("client credentials not sent: %v", gotForm)
			}
			if _, hasScope := gotForm["scope"]; hasScope != tc.wantKey {
				t.Fatalf("scope present = %v, want %v (form=%v)", hasScope, tc.wantKey, gotForm)
			}
			if gotForm.Get("scope") != tc.wantScope {
				t.Fatalf("scope = %q, want %q", gotForm.Get("scope"), tc.wantScope)
			}
		})
	}
}
